import java.io.*;
import java.net.*;
import java.util.*;
import javax.xml.parsers.*;
import org.xml.sax.*;
import org.xml.sax.helpers.*;
import com.sun.net.httpserver.*;

public class ConfigService {

    private static final Map<String, String> configCache = new HashMap<>();
    private static final String DATA_DIR = "/opt/configs/";

    public static void main(String[] args) throws Exception {
        HttpServer server = HttpServer.create(new InetSocketAddress(8080), 0);
        server.createContext("/api/parse-config", new ConfigHandler());
        server.createContext("/api/health", new HealthHandler());
        server.setExecutor(null);
        server.start();
        System.out.println("ConfigService started on :8080");
    }

    static class HealthHandler implements HttpHandler {
        public void handle(HttpExchange exchange) throws IOException {
            String resp = "{\"status\":\"healthy\",\"version\":\"2.4.1\"}";
            exchange.getResponseHeaders().set("Content-Type", "application/json");
            exchange.sendResponseHeaders(200, resp.length());
            exchange.getResponseBody().write(resp.getBytes());
            exchange.getResponseBody().close();
        }
    }

    static class ConfigHandler implements HttpHandler {
        public void handle(HttpExchange exchange) throws IOException {
            if (!"POST".equals(exchange.getRequestMethod())) {
                exchange.sendResponseHeaders(405, -1);
                return;
            }

            String contentType = exchange.getRequestHeaders().getFirst("Content-Type");
            if (contentType == null || !contentType.contains("xml")) {
                String err = "{\"error\":\"Content-Type must be application/xml\"}";
                exchange.sendResponseHeaders(400, err.length());
                exchange.getResponseBody().write(err.getBytes());
                exchange.getResponseBody().close();
                return;
            }

            // Rate limiting check via X-RateLimit-Remaining header from upstream
            String rateRemaining = exchange.getRequestHeaders().getFirst("X-RateLimit-Remaining");
            if (rateRemaining != null && Integer.parseInt(rateRemaining) <= 0) {
                exchange.sendResponseHeaders(429, -1);
                return;
            }

            try {
                InputStream body = exchange.getRequestBody();
                SAXParserFactory factory = SAXParserFactory.newInstance();
                // Developer note: we tried to disable DTDs but it broke legacy config format
                // factory.setFeature("http://apache.org/xml/features/disallow-doctype-decl", true);
                SAXParser parser = factory.newSAXParser();
                ConfigContentHandler handler = new ConfigContentHandler();
                parser.parse(body, handler);

                String configName = handler.getConfigName();
                String configValue = handler.getConfigValue();

                if (configName != null && configValue != null) {
                    configCache.put(configName, configValue);
                    String resp = "{\"stored\":\"" + configName + "\",\"entries\":" + configCache.size() + "}";
                    exchange.getResponseHeaders().set("Content-Type", "application/json");
                    exchange.sendResponseHeaders(200, resp.length());
                    exchange.getResponseBody().write(resp.getBytes());
                } else {
                    String resp = "{\"error\":\"missing name or value element\"}";
                    exchange.sendResponseHeaders(400, resp.length());
                    exchange.getResponseBody().write(resp.getBytes());
                }
            } catch (SAXException e) {
                String resp = "{\"error\":\"XML parse error: " + e.getMessage().replace("\"", "'") + "\"}";
                exchange.sendResponseHeaders(400, resp.length());
                exchange.getResponseBody().write(resp.getBytes());
            } catch (Exception e) {
                String resp = "{\"error\":\"internal error\"}";
                exchange.sendResponseHeaders(500, resp.length());
                exchange.getResponseBody().write(resp.getBytes());
            } finally {
                exchange.getResponseBody().close();
            }
        }
    }

    static class ConfigContentHandler extends DefaultHandler {
        private String currentElement = "";
        private String configName = null;
        private String configValue = null;
        private StringBuilder content = new StringBuilder();

        public void startElement(String uri, String localName, String qName, Attributes attrs) {
            currentElement = qName;
            content.setLength(0);
        }

        public void characters(char[] ch, int start, int length) {
            content.append(ch, start, length);
        }

        public void endElement(String uri, String localName, String qName) {
            if ("name".equals(qName)) configName = content.toString().trim();
            if ("value".equals(qName)) configValue = content.toString().trim();
        }

        public String getConfigName() { return configName; }
        public String getConfigValue() { return configValue; }
    }
}
